"""Debates acrescentados em novembro de 2026 (segunda leva). Mesmo formato de debates.py."""
SEP = 'https://plato.stanford.edu/entries/'
WE = 'https://en.wikipedia.org/wiki/'
TEMAS_DB2 = ['Justiça e Estado', 'Vida pessoal e relações', 'Tecnologia e futuro']
JE, VP, TF = TEMAS_DB2
RS, VM, LD, AN = 'Riqueza e sociedade', 'Vida e morte', 'Liberdade e dano', 'Animais'

DEBATES2 = [
dict(s='mentir', n='Mentir é sempre errado?', t=VP, r='Da mentira branca à mentira que salva vidas: Kant disse que nunca; quase todo mundo discorda. Onde fica a linha?',
 v='Mentir é afirmar o que se acredita falso com a intenção de enganar. Todas as tradições a condenam, e todas as pessoas mentem, em geral por pequenas coisas. A pergunta é se há mentiras permitidas, e o que as distingue.',
 lados=[('Contra toda mentira', ['Kant: mentir trata o outro como alguém que não merece decidir com a verdade; a máxima não é universalizável, porque se todos mentissem a mentira não funcionaria.', 'Confiança é um bem público: cada mentira, mesmo pequena, gasta um pouco dela, e a soma é um mundo em que ninguém acredita em ninguém.', 'Quem se permite mentiras “boas” rapidamente passa a achar boas as mentiras que lhe convêm.']),
        ('A favor de exceções', ['Mentir ao assassino que pergunta onde está a vítima: quase ninguém aceita a resposta de Kant. Há casos em que a verdade é cumplicidade.', 'A mentira branca que poupa um sentimento sem prejudicar ninguém tem custo quase nulo e benefício real; a honestidade brutal não é virtude.', 'Deontologistas pluralistas: a veracidade é um dever prima facie, que cede diante de deveres mais fortes.', 'Para as virtudes, a pessoa honesta não é a que despeja verdades, e sim a que encontra o jeito verdadeiro e gentil de falar.'])],
 c=['A mentira para proteger (o assassino) e a mentira para conveniência (“já estou chegando”) são casos muito diferentes, e a maioria das mentiras reais é do segundo tipo.', 'Enganar sem mentir (omitir, insinuar, dizer meia verdade) tem o mesmo efeito e escapa da regra; a questão é sobre enganar, não sobre a frase.', 'A confiança institucional (ciência, imprensa, governo) depende de uma norma de veracidade mais forte do que a das relações pessoais.'],
 p=('parcial', 'Quase todos os filósofos rejeitam o absolutismo kantiano: há mentiras permitidas, e a do assassino é o caso claro. Mas a defesa da mentira branca é mais fraca do que parece, porque o hábito corrói a confiança e porque quase sempre há uma verdade gentil disponível. A regra prática que sobrevive: mentir só quando a verdade causaria dano sério a quem não merece, e nunca por conveniência própria.'),
 teorias=[('deontologia-kantiana', 'Kant', 'Nunca: a mentira viola o dever de veracidade e a dignidade do outro.'), ('deontologia-pluralista', 'Ross', 'Dever prima facie de veracidade, que cede a deveres mais fortes.'), ('utilitarismo-classico', 'Utilitarismo', 'Depende das consequências, inclusive do efeito sobre a confiança geral.'), ('etica-das-virtudes', 'Virtudes', 'A honestidade é uma virtude; a crueldade com a verdade, um vício.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'A regra “não minta” produz mais bem do que “minta quando convier”; exceções só para casos extremos.')],
 licoes=['kant-e-o-imperativo-categorico', 'intencao-e-previsao', 'dilemas-do-cotidiano'],
 fx=[('Lying (Stanford Encyclopedia)', SEP + 'lying-definition/'), ('On a Supposed Right to Lie (Wikipédia)', WE + 'On_a_Supposed_Right_to_Lie_Because_of_Philanthropic_Concerns'), ('Lying: Moral Choice in Public and Private Life', 'https://www.google.com/search?tbm=bks&q=Sissela+Bok+Lying')]),

dict(s='ter-filhos', n='É certo ter filhos?', t=VP, r='O antinatalismo diz que nascer é sempre um dano. A maioria discorda, mas o argumento é mais difícil de responder do que parece.',
 v='Ter filhos foi, por quase toda a história, uma escolha que não se discutia. Hoje a pergunta se coloca de três formas: é errado criar alguém que vai sofrer? É irresponsável diante do clima e da superpopulação? E, do outro lado, há dever de ter filhos?',
 lados=[('Contra ter filhos, ou com fortes ressalvas', ['Benatar: há uma assimetria. A ausência de dor é boa mesmo que ninguém a desfrute; a ausência de prazer só é ruim para alguém que exista. Logo, não nascer nunca é pior, e nascer sempre tem custo.', 'Ninguém consente em nascer, e toda vida contém sofrimento sério, inclusive a morte.', 'Cada pessoa a mais em países ricos tem uma pegada ambiental enorme; e em um mundo com riscos sérios, criar alguém é apostar com a vida dele.', 'Há crianças já nascidas precisando de família; adotar faz o mesmo bem sem criar nova vulnerabilidade.']),
        ('A favor, ou contra a proibição moral', ['A assimetria de Benatar é contestada: a maioria das pessoas julga a própria vida digna de ser vivida, e isso é evidência contra a tese de que nascer é um dano.', 'Criar uma vida boa é criar valor; o antinatalismo implica que a extinção sem dor seria preferível, o que quase ninguém aceita.', 'Para a ética das virtudes e do cuidado, criar e cuidar de alguém é uma das formas centrais de florescimento humano.', 'A pegada é um argumento sobre como vivemos, não sobre existir: a mesma criança em um país de baixa emissão tem impacto pequeno.'])],
 c=['A ética populacional não tem solução aceita: toda teoria sobre criar pessoas leva a algum paradoxo.', 'A pergunta pessoal (devo ter filhos?) é diferente da política (deve haver políticas de natalidade?), e a segunda tem uma história sombria.', 'O consentimento é impossível por definição, e por isso não pode ser o critério: o que se pergunta é se a vida criada será provavelmente boa para quem a vive.'],
 p=('parcial', 'A maior parte dos filósofos rejeita o antinatalismo forte: a assimetria de Benatar não convence, e a evidência de que as pessoas valorizam suas vidas pesa contra a tese do dano. Mas o debate deixou algo: criar alguém é uma decisão moral séria, que pede condições de uma vida provavelmente boa, e a adoção merece mais peso do que costuma ter. Não há dever de ter filhos nem dever de não ter.'),
 teorias=[('etica-focada-no-sofrimento', 'Ética exclusivamente negativa', 'Contra: criar vidas não tem valor positivo, e toda vida tem sofrimento.'), ('utilitarismo-classico', 'Utilitarismo total', 'A favor, se a vida criada for boa: mais felicidade no mundo.'), ('prioridade-ao-sofrimento', 'Prioridade ao sofrimento', 'Cautela: o risco de uma vida ruim pesa mais do que a promessa de uma boa.'), ('etica-das-virtudes', 'Virtudes', 'Cuidar de uma nova vida é florescimento, se feito bem.'), ('deontologia-kantiana', 'Kant', 'Nenhum dever de criar pessoas; dever forte para com as que se cria.')],
 licoes=['etica-populacional', 'o-peso-do-sofrimento', 'geracoes-futuras'],
 fx=[('Better Never to Have Been', 'https://www.google.com/search?tbm=bks&q=Benatar+Better+Never+to+Have+Been'), ('The Repugnant Conclusion (Stanford Encyclopedia)', SEP + 'repugnant-conclusion/'), ('Antinatalism (Wikipédia)', WE + 'Antinatalism')]),

dict(s='venda-de-orgaos', n='Doação e venda de órgãos', t=VM, r='Milhares morrem na fila. Consentimento presumido resolveria parte; um mercado regulado, talvez o resto. Por que a ideia causa tanta repulsa?',
 v='Faltam órgãos em todos os países. Duas propostas aumentam a oferta: presumir que todos são doadores, salvo recusa registrada; e permitir que vivos vendam um rim, em mercado regulado. A primeira é adotada em vários países; a segunda, só no Irã.',
 lados=[('A favor de ampliar: presunção e mercado regulado', ['Consentimento presumido: a maioria é a favor de doar e não registra; inverter o padrão salva vidas sem forçar ninguém, porque a recusa continua possível.', 'Mercado regulado: pessoas já vendem trabalho perigoso, e a venda de um rim, com triagem médica e preço fixo, salvaria milhares que hoje morrem; a proibição não acabou com o mercado, só o empurrou para a clandestinidade.', 'Autonomia: proibir que um adulto informado venda um rim para pagar a faculdade do filho é paternalismo.']),
        ('Contra, sobretudo o mercado', ['Exploração: quem vende será pobre; a escolha “livre” sob necessidade não é livre, e o corpo dos pobres viraria reserva dos ricos.', 'Mercantilização: há coisas que não devem ter preço, e vender partes do corpo corrói a ideia de dignidade (Sandel).', 'Evidência: no Irã, vendedores relatam arrependimento, estigma e piora de vida.', 'Sobre a presunção: o Estado dispor do corpo por padrão inverte a lógica do consentimento; famílias se sentem desrespeitadas, e a oferta nem sempre sobe.'])],
 c=['A presunção de consentimento e o mercado são questões separadas; a primeira tem muito mais apoio.', 'A repulsa a vender órgãos é forte e pode ser um guia moral ou um viés; a pergunta é se as razões a sustentam.', 'Alternativas intermediárias: compensação não monetária, prioridade na fila para doadores registrados, cobertura de custos.'],
 p=('parcial', 'Sobre o consentimento presumido com recusa fácil, o peso está a favor: salva vidas e preserva a escolha. Sobre o mercado de órgãos, o debate é real: o argumento da exploração é sério, e a evidência iraniana o apoia, mas a proibição também mata, e filósofos como Janet Radcliffe Richards mostraram que as objeções usuais provam menos do que parecem. A posição mais defendida é ampliar a doação por todos os meios não monetários antes de discutir o mercado.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'A favor do que aumentar a oferta sem dano líquido, inclusive mercado regulado.'), ('deontologia-de-direitos', 'Direitos', 'Dividida: autonomia sobre o corpo contra o direito de não ser explorado.'), ('deontologia-kantiana', 'Kant', 'Contra vender partes de si: a pessoa não é mercadoria.'), ('etica-do-cuidado', 'Cuidado', 'Olha quem venderia e por quê; a resposta costuma ser pobreza, e a pergunta vira outra.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, aceitaríamos a presunção; o mercado, só com proteções fortes.')],
 licoes=['fazer-e-deixar-acontecer', 'pobreza-e-etica-global', 'direitos-e-limiares'],
 fx=[('The Ethics of Transplants', 'https://www.google.com/search?tbm=bks&q=Janet+Radcliffe+Richards+The+Ethics+of+Transplants'), ('Organ donation (Wikipédia)', WE + 'Organ_donation'), ('O Que o Dinheiro Não Compra', 'https://www.google.com/search?tbm=bks&q=Sandel+O+que+o+dinheiro+n%C3%A3o+compra')]),

dict(s='tortura', n='Tortura: nunca, ou na bomba-relógio?', t=JE, r='O caso hipotético em que torturar um terrorista salvaria milhares. O que ele prova, e o que ele esconde.',
 v='A tortura é proibida sem exceção pelo direito internacional. O cenário da bomba-relógio desafia a proibição: um terrorista preso sabe onde está uma bomba que matará milhares; só a tortura o fará falar a tempo. A maioria das pessoas, diante do caso, aceita torturar. Filósofos perguntam se o caso é real e o que uma exceção faz com a regra.',
 lados=[('Contra, sem exceção', ['A tortura é o uso mais completo de uma pessoa como meio: destrói a vontade para extrair algo dela. Se algum direito é absoluto, é o de não ser torturado.', 'O cenário nunca é como no exemplo: não se sabe se o preso sabe, se falará a verdade, se há tempo. A exceção hipotética legaliza a prática real, que é usada contra suspeitos, não contra terroristas certos.', 'Evidência: a tortura produz confissões falsas; interrogatórios sem coerção funcionam melhor.', 'Instituições que admitem exceção criam torturadores profissionais, e a história mostra para onde isso vai.']),
        ('A favor da exceção extrema', ['Deontologia de limiar: se milhares de vidas estão em jogo, a restrição cede; recusar é preferir a própria pureza às vítimas.', 'Consequencialismo: se, e só se, as condições do caso fossem reais, a conta é clara.', 'Dershowitz: já que será feita, é melhor que seja com autorização judicial e limites do que escondida.'])],
 c=['A diferença entre “seria permitido no caso ideal” e “deve ser legal” é o centro do debate: pode-se aceitar a primeira e negar a segunda.', 'Alguns defendem que, no caso extremo, o agente deve torturar e aceitar punição: a regra fica intacta, e a exceção fica com quem a assume.', 'O cenário é um experimento mental sobre limites, não um guia de política, e usá-lo como guia foi o erro de governos reais.'],
 p=('forte', 'Sobre a tortura como prática legal, o consenso filosófico, jurídico e empírico é contra: a exceção hipotética não descreve nenhum caso real, e sua legalização produz tortura de inocentes e confissões falsas. O que fica em aberto é o veredito sobre o caso ideal, em que deontologistas de limiar e consequencialistas admitem a exceção, e absolutistas não; mas mesmo quem a admite costuma defender que a lei não a reconheça.'),
 teorias=[('deontologia-absolutista', 'Absolutismo', 'Nunca: a restrição não cede a número algum.'), ('deontologia-de-limiar', 'Limiar', 'No caso ideal, sim; na prática, a condição nunca se cumpre.'), ('utilitarismo-classico', 'Utilitarismo', 'Depende das consequências reais, que incluem a instituição da tortura, não só o caso.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'A regra “nunca torture” produz mais bem do que qualquer regra com exceções.'), ('deontologia-kantiana', 'Kant', 'Nunca: é o uso extremo de uma pessoa apenas como meio.')],
 licoes=['direitos-e-limiares', 'deontologia', 'incerteza-moral'],
 fx=[('Torture (Stanford Encyclopedia)', SEP + 'torture/'), ('Ticking time bomb scenario (Wikipédia)', WE + 'Ticking_time_bomb_scenario')]),

dict(s='guerra-justa', n='Existe guerra justa?', t=JE, r='Pacifismo, guerra justa e realismo: quando, se alguma vez, matar em escala é permitido, e com que regras.',
 v='A tradição da guerra justa, de Agostinho a Walzer, diz que a guerra pode ser permitida sob condições estritas: causa justa, último recurso, proporcionalidade, e regras na condução, como não atacar civis. O pacifismo nega; o realismo diz que a moral não se aplica à guerra.',
 lados=[('A tradição da guerra justa', ['Defesa contra agressão é legítima defesa em escala: se um indivíduo pode se defender, um povo também.', 'Sem a possibilidade de guerra justa, agressores vencem sempre; o pacifismo absoluto entrega o mundo a quem não é pacifista.', 'As regras de condução (distinção entre combatentes e civis, proporcionalidade, não usar certos meios) limitam o horror e são aplicáveis.', 'Intervenção humanitária: há casos, como genocídios, em que não intervir é cumplicidade.']),
        ('Pacifismo e ceticismo', ['Toda guerra mata inocentes em massa, inclusive as justas; o duplo efeito tem servido para aceitar isso com facilidade demais.', 'Quase toda guerra é declarada justa por quem a faz; o critério é manipulável, e a história de guerras “justas” é uma história de desastres.', 'McMahan: soldados do lado injusto não têm o mesmo direito de matar que os do lado justo, o que torna a maior parte das mortes em guerra assassinato.', 'Métodos não violentos tiveram sucesso em mais casos do que se pensa, segundo pesquisas comparativas.'])],
 c=['A guerra justa é uma teoria sobre casos raros aplicada a casos comuns; quase nenhuma guerra real cumpre as condições.', 'Armas modernas tornam a distinção entre combatentes e civis mais difícil, e as armas nucleares a tornam impossível.', 'Quem decide? Instituições internacionais são fracas, e a decisão fica com os próprios interessados.'],
 p=('parcial', 'A maior parte dos filósofos aceita que a defesa contra agressão pode ser justa, e rejeita o pacifismo absoluto e o realismo. Mas a crítica pacifista acertou em algo importante: as condições são quase nunca cumpridas, e o duplo efeito tem sido usado para aceitar mortes de civis que a teoria deveria proibir. O peso prático está em exigir muito mais do que se exige, e em dar às alternativas não violentas o crédito que a evidência lhes dá.'),
 teorias=[('doutrina-do-duplo-efeito', 'Duplo efeito', 'Permite atacar alvos militares prevendo mortes civis, se proporcionais; é o núcleo das regras de condução.'), ('deontologia-de-direitos', 'Direitos', 'Legítima defesa em escala; civis mantêm o direito de não ser atacados.'), ('utilitarismo-classico', 'Utilitarismo', 'Guerra só se o resultado esperado for melhor do que o da paz, contando todos os afetados.'), ('deontologia-absolutista', 'Absolutismo', 'Pacifismo, em algumas versões: matar inocentes nunca, e toda guerra o faz.'), ('contratualismo-escanloniano', 'Scanlon', 'Que regras de guerra ninguém poderia rejeitar? As que protegem civis e limitam meios.')],
 licoes=['intencao-e-previsao', 'catastrofes-morais', 'riscos-s-e-riscos-x'],
 fx=[('War (Stanford Encyclopedia)', SEP + 'war/'), ('Guerras Justas e Injustas', 'https://www.google.com/search?tbm=bks&q=Walzer+Guerras+Justas+e+Injustas'), ('Killing in War', 'https://www.google.com/search?tbm=bks&q=McMahan+Killing+in+War')]),

dict(s='imigracao', n='Fronteiras abertas?', t=JE, r='O lugar de nascimento é a maior loteria da vida. Que direito um país tem de impedir alguém de entrar?',
 v='Nascer em um país rico ou pobre decide mais da vida de uma pessoa do que qualquer esforço. Controles de imigração mantêm essa loteria. A pergunta ética é se um Estado tem direito de excluir, e com que justificativa; a pergunta prática é o que acontece quando as fronteiras se abrem ou se fecham.',
 lados=[('A favor de fronteiras muito mais abertas', ['Carens: a cidadania por nascimento é como o feudalismo, um privilégio herdado que decide a vida; a imparcialidade não aceita o lugar de nascimento como razão moral.', 'Liberdade de movimento é um direito dentro dos países; não há razão de princípio para que termine na fronteira.', 'Economia: a migração aumenta a renda dos migrantes de forma enorme e, segundo a maior parte dos estudos, beneficia ou não prejudica os países de destino no agregado.', 'Quem foge de guerra, perseguição ou miséria tem um direito que nenhuma soberania supera.']),
        ('A favor do direito de controlar', ['Autodeterminação: uma comunidade política tem direito de decidir quem entra, como uma associação decide seus membros (Walzer, Miller).', 'Instituições, confiança e Estado de bem-estar dependem de coesão, que migração rápida demais pode corroer.', 'Deveres especiais com os compatriotas, sobretudo os mais pobres, que competem por salários e serviços.', 'Abertura total poderia desestabilizar países de destino e esvaziar os de origem de seus profissionais.'])],
 c=['“Abertas” e “fechadas” são extremos que ninguém defende; a questão é quanto e como, e a evidência sobre efeitos varia por contexto e velocidade.', 'Deveres com compatriotas são reais, mas não implicam que estrangeiros não contem; a pergunta é quanto peso a mais a nacionalidade pode ter.', 'A causa da migração forçada (guerra, clima, pobreza) muitas vezes envolve os países de destino, o que muda o dever de reparação.'],
 p=('parcial', 'Em princípio, o peso está com a abertura: o lugar de nascimento não é razão moral, e a evidência econômica favorece a migração. Os argumentos de autodeterminação e coesão têm força sobre o ritmo e as condições, não sobre o direito de excluir quem foge de perigo. A posição mais defendida é muito mais abertura do que a atual, com instituições que distribuam os custos de transição.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'A favor da abertura: ganhos enormes para migrantes, efeitos pequenos ou positivos nos destinos.'), ('contratualismo-rawlsiano', 'Contratualismo (Carens)', 'Sob um véu global, ninguém aceitaria fronteiras que o prendessem na pobreza.'), ('deontologia-de-direitos', 'Direitos', 'Liberdade de movimento e asilo como direitos; propriedade coletiva do território como contra-argumento.'), ('etica-do-cuidado', 'Cuidado', 'Começa pelos próximos, mas não termina neles; o refugiado na fronteira é o próximo.'), ('egoismo-etico', 'Egoísmo nacional', 'Só os nossos contam; é a posição que a imparcialidade questiona.')],
 licoes=['tribalismo-moral', 'igualdade-humana', 'pobreza-e-etica-global'],
 fx=[('Immigration (Stanford Encyclopedia)', SEP + 'immigration/'), ('The Ethics of Immigration', 'https://www.google.com/search?tbm=bks&q=Joseph+Carens+The+Ethics+of+Immigration'), ('Imigração (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/debates/imigracao.html')]),

dict(s='punicao', n='Punir por merecimento ou para prevenir?', t=JE, r='Retribuição, dissuasão, reabilitação, proteção: o que justifica a prisão, e o que isso muda em como punimos.',
 v='Punir é impor sofrimento de propósito a alguém. Isso exige justificativa. As teorias se dividem entre as que olham para trás (a pessoa merece) e as que olham para a frente (a punição evita crimes, reabilita ou protege). A escolha muda quem punir, quanto e como.',
 lados=[('Retributivismo', ['Quem faz o mal merece sofrer na proporção do mal; a punição é justiça, não cálculo (Kant).', 'Só o merecimento impede punir inocentes ou punir demais por utilidade: a dissuasão pura aceitaria enforcar um inocente se isso assustasse os outros.', 'A punição reconhece o criminoso como agente responsável, e não como paciente a ser tratado.', 'Vítimas e sociedade têm razão em sentir que o crime pede resposta proporcional.']),
        ('Consequencialismo da punição', ['Sofrimento só se justifica pelo que evita: dissuasão, incapacitação, reabilitação. Sofrimento sem efeito é só mais sofrimento.', 'Evidência: a certeza da punição dissuade mais do que a severidade; penas longas pouco acrescentam; prisões degradantes aumentam a reincidência; sistemas voltados à reabilitação (Noruega) têm reincidência menor.', 'O merecimento é difícil de medir e, segundo muitos, pressupõe um livre-arbítrio que a ciência questiona: pobreza, trauma e biologia moldam quem comete crimes.', 'O retributivismo real degenera em vingança e em populismo penal.'])],
 c=['A maioria dos filósofos combina as duas: a punição precisa de merecimento como condição (não punir inocentes) e de consequências como justificativa (não punir sem propósito).', 'O Brasil tem a terceira maior população carcerária do mundo, com reincidência alta e prisões que a Justiça já chamou de estado de coisas inconstitucional; o sistema real não serve a nenhuma das teorias.', 'Justiça restaurativa, que envolve vítima e ofensor na reparação, é uma terceira via com evidência crescente.'],
 p=('parcial', 'O retributivismo acertou em um ponto que ninguém mais abandona: não se pune inocentes nem além do merecido, por mais útil que fosse. Mas, dentro desse limite, o peso está com as consequências: a evidência mostra que severidade sem certeza não dissuade, que prisões degradantes criam mais crime, e que reabilitação e justiça restaurativa reduzem a reincidência. Punir mais do que o necessário para prevenir é somar sofrimento sem retorno.'),
 teorias=[('deontologia-kantiana', 'Kant', 'Retribuição: o merecimento justifica e mede a pena.'), ('utilitarismo-classico', 'Utilitarismo (Bentham)', 'Só a prevenção justifica; toda punição é um mal em si, a ser minimizado.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Regras de punição justas (só culpados, proporcional) produzem mais bem do que cálculos caso a caso.'), ('etica-das-virtudes', 'Virtudes', 'O que a punição faz do punidor e da comunidade; vingança é vício.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, aceitaríamos punição que protege, com garantias contra o erro.')],
 licoes=['fazer-e-deixar-acontecer', 'direitos-e-limiares', 'da-etica-a-politica'],
 fx=[('Punishment (Stanford Encyclopedia)', SEP + 'punishment/'), ('Legal Punishment (Stanford Encyclopedia)', SEP + 'legal-punishment/'), ('Segurança pública (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/debates/seguranca-publica.html')]),

dict(s='paternalismo', n='O Estado pode proteger você de si mesmo?', t=LD, r='Cinto de segurança, capacete, açúcar, jogo, drogas: quando interferir na escolha de um adulto para o próprio bem dele é aceitável?',
 v='Paternalismo é interferir na liberdade de alguém, contra a vontade dela, para o bem dela. Mill o rejeitou: sobre o que afeta só a si mesmo, o adulto é soberano. Mas aceitamos cinto obrigatório, proibição de vender-se como escravo e regras contra remédios perigosos. A pergunta é qual critério separa o paternalismo aceitável do inaceitável.',
 lados=[('Contra o paternalismo', ['Mill: cada pessoa é a melhor juíza do próprio bem, e o hábito de interferir leva a interferir em tudo.', 'Autonomia é parte do bem-estar: uma vida escolhida vale mais do que uma vida imposta, mesmo que pior em outros aspectos.', 'O Estado erra e tem interesses; dar-lhe o poder de decidir o que é bom para cada um é perigoso.', 'Adultos têm direito de correr riscos: montanhismo, dieta, religião.']),
        ('A favor de algum paternalismo', ['Paternalismo fraco: interferir quando a escolha não é informada ou voluntária (pessoa bêbada, viciada, enganada) respeita a autonomia em vez de violá-la.', 'Vieses: as pessoas subestimam riscos e descontam o futuro; “empurrões” (nudges) que preservam a escolha corrigem isso a custo baixo.', 'Quase nada afeta só a si: o acidentado sem cinto custa ao sistema de saúde e à família.', 'Mill mesmo proibia vender-se como escravo: a liberdade de abdicar da liberdade não vale.'])],
 c=['A linha de Mill entre o que afeta só a si e o que afeta outros é mais difícil do que ele admitiu.', 'Há diferença entre proibir, taxar, informar e desenhar o padrão: o paternalismo libertário de Thaler e Sunstein tenta ficar no último.', 'Quem define o “bem” da pessoa? Se é o próprio critério dela, o paternalismo fraco é aceitável; se é o do Estado, não.'],
 p=('parcial', 'O peso está contra o paternalismo forte: proibir escolhas informadas e voluntárias de adultos para o bem deles raramente se justifica. Mas o paternalismo fraco (garantir informação e voluntariedade) e os empurrões que preservam a escolha são aceitos pela maioria, e a evidência sobre vieses lhes dá base. A pergunta útil é sempre: a interferência preserva a capacidade de escolher, ou a substitui?'),
 teorias=[('utilitarismo-classico', 'Utilitarismo (Mill)', 'Contra: a soberania sobre si produz mais bem a longo prazo; exceções para escolhas não voluntárias.'), ('deontologia-kantiana', 'Kant', 'Contra tratar adultos como crianças; a favor de proteger a própria autonomia (não vender-se).'), ('deontologia-de-direitos', 'Direitos', 'Contra: o corpo e a vida são de quem os tem.'), ('etica-do-cuidado', 'Cuidado', 'A favor de cuidar, contra impor; a diferença está em ouvir a pessoa.'), ('etica-das-virtudes', 'Virtudes', 'O Estado não forma virtude por decreto; a prudência se aprende escolhendo.')],
 licoes=['vieses-morais', 'fraqueza-de-vontade', 'da-etica-a-politica'],
 fx=[('Paternalism (Stanford Encyclopedia)', SEP + 'paternalism/'), ('Sobre a Liberdade', 'https://pt.wikipedia.org/wiki/Sobre_a_Liberdade'), ('Nudge', 'https://www.google.com/search?tbm=bks&q=Thaler+Sunstein+Nudge')]),

dict(s='meritocracia', n='Meritocracia é justa?', t=RS, r='Recompensar o mérito parece óbvio. Mas de onde vem o mérito, e o que acontece com quem não o tem?',
 v='Meritocracia é a ideia de que posições e recompensas devem ir para os mais capazes e esforçados, e não para os bem-nascidos. Nasceu como ideal igualitário contra a aristocracia. A crítica atual pergunta se o mérito não é, ele mesmo, em grande parte herdado, e se uma sociedade organizada por ele é boa para quem fica embaixo.',
 lados=[('A favor', ['É melhor do que a alternativa histórica: cargos por nascimento, cor ou conexões.', 'Recompensar esforço e competência produz mais e dá a cada um razão para se desenvolver.', 'Igualdade de oportunidades é o que torna a competição justa; o problema é a falta dela, não o mérito.', 'As pessoas são agentes: tratar o esforço como pura sorte nega a responsabilidade.']),
        ('Contra, ou com fortes ressalvas', ['Rawls: talento, família, saúde e até a disposição para o esforço vêm da loteria natural e social; ninguém merece o ponto de partida, e por isso ninguém merece, no sentido forte, o que sai dele.', 'Sandel: a meritocracia faz os vencedores acreditarem que merecem tudo e os perdedores que merecem nada; o resultado é arrogância em cima e humilhação embaixo.', 'Na prática, o “mérito” medido (notas, diplomas, redes) é comprado pelas famílias ricas; a mobilidade é baixa onde a retórica meritocrática é mais forte.', 'Mesmo com oportunidades iguais, por que o menos talentoso deveria viver pior? A desigualdade de resultado não decorre da igualdade de chance.'])],
 c=['Mérito como critério para preencher cargos (o cirurgião mais competente) é diferente de mérito como critério de quem merece viver bem.', 'A igualdade de oportunidades real exigiria neutralizar a família, o que ninguém quer; a tensão é permanente.', 'Rejeitar o merecimento forte não implica abolir incentivos: pode-se recompensar o esforço por suas consequências sem acreditar que ele é merecido.'],
 p=('parcial', 'Como critério para distribuir posições, o mérito vence as alternativas. Como justificativa moral da desigualdade de vidas, não se sustenta: o ponto de partida não é merecido, e a filosofia desde Rawls converge nisso. A posição mais defendida é usar o mérito para selecionar e os incentivos para motivar, sem concluir que quem ficou embaixo merece ficar.'),
 teorias=[('contratualismo-rawlsiano', 'Rawls', 'Desigualdades só se beneficiarem quem está pior; o mérito não funda merecimento.'), ('utilitarismo-classico', 'Utilitarismo', 'Incentivos ao mérito valem pelo que produzem; a desigualdade resultante vale só se melhorar o total.'), ('deontologia-de-direitos', 'Libertarismo', 'O que se ganha em trocas justas é merecido, talento herdado ou não.'), ('prioritarismo', 'Prioritarismo', 'Um ganho para quem está pior vale mais, mérito à parte.'), ('etica-das-virtudes', 'Virtudes', 'O mérito que importa é o caráter, e ele não aparece em rankings.')],
 licoes=['igualdade-humana', 'somar-priorizar-ou-garantir', 'economia-politica-e-etica'],
 fx=[('A Tirania do Mérito', 'https://www.google.com/search?tbm=bks&q=Sandel+A+Tirania+do+M%C3%A9rito'), ('Desert (Stanford Encyclopedia)', SEP + 'desert/'), ('Uma Teoria da Justiça', 'https://pt.wikipedia.org/wiki/Uma_Teoria_da_Justi%C3%A7a')]),

dict(s='edicao-genetica', n='Editar genes humanos', t=TF, r='Curar doenças no embrião, quase todos aceitam. Escolher altura, inteligência ou cor dos olhos, a maioria rejeita. Por quê?',
 v='Técnicas como CRISPR permitem alterar o DNA de embriões, com efeitos herdáveis. Duas aplicações se distinguem: terapia (evitar doenças graves) e melhoramento (escolher traços). Em 2018, um cientista chinês editou bebês e foi condenado; a comunidade científica pede moratória para edições herdáveis.',
 lados=[('A favor, com limites', ['Evitar doenças devastadoras em uma criança é o mesmo bem que a medicina sempre buscou; recusar por “naturalidade” é a falácia naturalista.', 'Pais já escolhem muito do futuro dos filhos (escola, dieta, ambiente); a edição é mais uma forma, e potencialmente mais justa se for acessível.', 'Savulescu: há um dever de dar aos filhos a melhor vida possível, o que inclui evitar sofrimento evitável.', 'A proibição total empurra a prática para lugares sem regulação.']),
        ('Contra, sobretudo o melhoramento', ['Segurança: efeitos herdáveis e irreversíveis, com riscos desconhecidos para quem não pode consentir.', 'Desigualdade: se o melhoramento for comprado, cria-se uma elite genética; a loteria natural vira loteria de renda.', 'Sandel: a busca por perfeição corrói a aceitação do filho como dádiva e a humildade diante do que não controlamos.', 'Habermas: a pessoa editada não é autora da própria vida do mesmo modo; outro decidiu quem ela seria.', 'Pressão social: o que começa como opção vira exigência, como já acontece com testes pré-natais.'])],
 c=['A linha entre terapia e melhoramento é borrada: aumentar a imunidade é terapia ou melhoramento?', 'O argumento da desigualdade é sobre acesso, não sobre a técnica; vale para toda medicina cara.', 'Incerteza científica alta hoje; o debate moral se mistura com o debate sobre segurança, que muda com o tempo.'],
 p=('parcial', 'Sobre terapia para doenças graves, o peso está a favor, condicionado à segurança, que hoje não existe para edições herdáveis. Sobre melhoramento, o debate é real: os argumentos de segurança, desigualdade e pressão social pesam contra agora, mas são argumentos sobre condições, e não sobre a técnica em si. As objeções de princípio (Sandel, Habermas) são levadas a sério e também contestadas.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'A favor do que reduzir sofrimento com segurança, inclusive melhoramento se o acesso for justo.'), ('deontologia-kantiana', 'Kant (Habermas)', 'Cautela: decidir a natureza de outra pessoa pode violar sua autonomia futura.'), ('etica-das-virtudes', 'Virtudes (Sandel)', 'A humildade e a aceitação são virtudes que a busca por controle total corrói.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, aceitaríamos terapia para todos; melhoramento só se não criasse castas.'), ('prioridade-ao-sofrimento', 'Prioridade ao sofrimento', 'Evitar doenças devastadoras tem prioridade; melhoramento, não.')],
 licoes=['geracoes-futuras', 'igualdade-humana', 'probabilidade-e-etica'],
 fx=[('Human Enhancement (Stanford Encyclopedia)', SEP + 'enhancement/'), ('Contra a Perfeição', 'https://www.google.com/search?tbm=bks&q=Sandel+Contra+a+Perfei%C3%A7%C3%A3o'), ('He Jiankui affair (Wikipédia)', WE + 'He_Jiankui_affair')]),

dict(s='vigilancia-e-privacidade', n='Vigilância e privacidade', t=TF, r='“Quem não deve, não teme”? A privacidade vale por si, ou só pelo que protege? E o que a vigilância em massa faz com uma sociedade?',
 v='Câmeras com reconhecimento facial, dados de celular, histórico de navegação: governos e empresas sabem mais sobre cada pessoa do que qualquer polícia do passado. A justificativa é segurança e conveniência. A pergunta é o que se perde, e se a troca é justa.',
 lados=[('A favor da privacidade como limite forte', ['Privacidade é condição da autonomia: quem é observado o tempo todo se comporta como observado, e deixa de experimentar, dissentir e errar.', 'Poder: quem tem os dados tem poder sobre quem os deu, e esse poder foi usado contra dissidentes, minorias e jornalistas em toda democracia que o teve.', '“Quem não deve, não teme” pressupõe que quem define o que se deve é confiável para sempre; regimes mudam, e os dados ficam.', 'Consentimento falso: ninguém lê os termos, e a alternativa é ficar fora da vida social.']),
        ('A favor da vigilância, com controles', ['Segurança real: câmeras e dados resolvem crimes e evitam ataques; recusar isso tem vítimas concretas.', 'Conveniência e serviços melhores dependem de dados; a maioria aceita a troca quando ela é clara.', 'Transparência pode valer para os dois lados: vigiar os vigilantes.', 'A privacidade não é absoluta: pesa contra outros bens, e às vezes perde.'])],
 c=['Vigilância direcionada, com autorização judicial, é diferente de vigilância em massa; a maior parte do debate confunde as duas.', 'Empresas e Estados são ameaças diferentes, e a defesa contra uma pode fortalecer a outra.', 'A evidência sobre o efeito das câmeras no crime é modesta e depende do contexto.'],
 p=('parcial', 'O peso está com a privacidade como limite forte à vigilância em massa: o argumento do poder acumulado e do comportamento sob observação é aceito pela maioria, e a evidência de abuso é histórica. Vigilância direcionada, com controle judicial e prazo, tem defesa; vigilância total não. O desacordo real está em onde fica a linha e em quem a fiscaliza.'),
 teorias=[('deontologia-de-direitos', 'Direitos', 'A privacidade como direito, trunfo contra a conveniência coletiva.'), ('utilitarismo-classico', 'Utilitarismo', 'Depende: contar o efeito sobre a autonomia e o abuso futuro, não só os crimes evitados hoje.'), ('deontologia-kantiana', 'Kant', 'Observar e manipular pessoas sem consentimento as trata como meios.'), ('contratualismo-rawlsiano', 'Contratualismo', 'Sob o véu, sem saber se seria o dissidente ou o governo, que regras de vigilância aceitaríamos?'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Regras fortes de privacidade produzem mais bem do que decidir caso a caso.')],
 licoes=['direitos-e-limiares', 'da-etica-a-politica', 'catastrofes-morais'],
 fx=[('Privacy (Stanford Encyclopedia)', SEP + 'privacy/'), ('A Era do Capitalismo de Vigilância', 'https://www.google.com/search?tbm=bks&q=Zuboff+A+Era+do+Capitalismo+de+Vigil%C3%A2ncia'), ('Privacidade (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/privacidade.html')]),

dict(s='desobediencia-civil', n='Desobedecer a lei pode ser certo?', t=JE, r='Quebrar a lei para corrigir uma injustiça, abertamente e aceitando as consequências: de Thoreau a Gandhi e King, e os limites da ideia.',
 v='Leis podem ser injustas, e a história das conquistas morais é cheia de gente que as desobedeceu: abolicionistas, sufragistas, o movimento pelos direitos civis. A questão é quando a desobediência é justificada, e o que a distingue de simples crime ou de violência política.',
 lados=[('A favor, sob condições', ['Rawls: em uma sociedade quase justa, a desobediência civil é legítima quando pública, não violenta, dirigida a uma injustiça séria, depois de esgotados os meios legais, e aceitando a punição; ela apela ao senso de justiça da maioria.', 'King: uma lei injusta não é lei no sentido pleno; obedecê-la é cumplicidade.', 'Sem desobediência, injustiças legais só mudariam quando os beneficiados quisessem; a história mostra que não querem.', 'Aceitar a punição mostra respeito pela ordem legal em geral e sinceridade da convicção.']),
        ('Cautela e limites', ['Cada um acha sua causa justa; se a desobediência for permitida a todos que se julgam certos, não há lei.', 'Em democracias, há meios legais de mudar leis; quebrá-las desrespeita a decisão dos concidadãos.', 'A linha para a violência é fácil de cruzar, e “ação direta” já justificou ataques a pessoas.', 'Efeito: a desobediência pode endurecer a maioria contra a causa.'])],
 c=['A desobediência civil clássica é pública e não violenta; sabotagem clandestina e violência são outra coisa, com outra justificativa (ou nenhuma).', 'Quanto mais injusta a sociedade, menos as condições de Rawls se aplicam: contra uma ditadura, a questão é outra.', 'Causas de hoje (clima, animais) testam as condições: a injustiça é séria? Os meios legais se esgotaram? Quem são as vítimas?'],
 p=('parcial', 'Há consenso de que a desobediência civil pode ser justificada, e as condições de Rawls são o padrão aceito: injustiça séria, meios legais esgotados, ação pública e não violenta, aceitação da punição. O desacordo está na aplicação: quando a injustiça é “séria o bastante” e quando os meios se esgotaram. A história julga com generosidade quem desobedeceu por causas depois reconhecidas, e com dureza quem desobedeceu pelas outras.'),
 teorias=[('contratualismo-rawlsiano', 'Rawls', 'Legítima sob condições, como apelo ao senso de justiça da maioria.'), ('deontologia-de-direitos', 'Direitos', 'Leis que violam direitos básicos não obrigam.'), ('utilitarismo-classico', 'Utilitarismo', 'Depende do efeito: desobediência que acelera a correção vale; a que endurece a maioria, não.'), ('etica-das-virtudes', 'Virtudes', 'Coragem cívica é virtude; o desprezo pela lei em geral, não.'), ('deontologia-kantiana', 'Kant', 'Kant era contra; kantianos de hoje admitem resistência a leis que violam a dignidade.')],
 licoes=['progresso-moral', 'expansao-do-circulo-moral', 'da-etica-a-politica'],
 fx=[('Civil Disobedience (Stanford Encyclopedia)', SEP + 'civil-disobedience/'), ('Carta da Prisão de Birmingham (Wikipédia)', WE + 'Letter_from_Birmingham_Jail'), ('Regras e desobediência (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/regras-e-desobediencia.html')]),

dict(s='cotas', n='Cotas e ações afirmativas', t=JE, r='Reservar vagas por raça ou renda corrige uma injustiça ou cria outra? O que a evidência brasileira diz.',
 v='Ações afirmativas reservam vagas em universidades, concursos ou empresas para grupos historicamente excluídos. No Brasil, a lei de cotas de 2012 reservou metade das vagas federais para alunos de escola pública, com subcotas por renda, cor e deficiência. O debate ético opõe correção de injustiça a igualdade formal.',
 lados=[('A favor', ['Reparação: a exclusão de negros e pobres não foi acidente, foi política; corrigir seus efeitos é dever de justiça, não favor.', 'Igualdade real: tratar como iguais pessoas em pontos de partida radicalmente desiguais perpetua a desigualdade; a imparcialidade exige olhar o ponto de partida.', 'Evidência: cotistas no Brasil têm desempenho próximo ao dos demais e se formam em taxas semelhantes; a diversidade melhora o ambiente e as instituições.', 'Mérito medido por vestibular mede, em boa parte, renda familiar.']),
        ('Contra, ou por outros critérios', ['Igualdade formal: julgar pela cor, mesmo para incluir, usa o critério que o racismo usou.', 'Quem paga é um indivíduo que não causou a injustiça; corrigir uma injustiça coletiva com um custo individual é problemático.', 'Estigma: beneficiários podem ser vistos como menos capazes.', 'Cotas por renda atingiriam o mesmo público sem usar a cor; e o problema real está na educação básica, não na porta da universidade.'])],
 c=['Cotas são uma medida transitória de correção, não uma teoria da justiça permanente; a pergunta é por quanto tempo e com que critérios.', 'A evidência brasileira é bem mais favorável do que o debate público sugere, e o custo para não cotistas foi pequeno.', 'Raça e renda se sobrepõem, mas não coincidem: a discriminação racial opera também sobre negros de renda média.'],
 p=('parcial', 'A favor, como medida transitória: a evidência brasileira de desempenho e conclusão desmonta a objeção do mérito, e a imparcialidade pede olhar o ponto de partida, não só a linha de chegada. As objeções mais fortes são sobre desenho (critérios, duração, estigma, prioridade à educação básica), e merecem resposta; a objeção de princípio, de que usar a cor para incluir é como usá-la para excluir, é rejeitada pela maioria dos filósofos, porque o propósito e o efeito são opostos.'),
 teorias=[('contratualismo-rawlsiano', 'Rawls', 'Igualdade equitativa de oportunidades exige corrigir pontos de partida.'), ('utilitarismo-classico', 'Utilitarismo', 'A favor se o ganho dos incluídos e das instituições supera o custo dos excluídos, o que a evidência indica.'), ('deontologia-de-direitos', 'Libertarismo', 'Contra: tratamento igual perante a lei, sem critérios de grupo.'), ('prioritarismo', 'Prioritarismo', 'A favor: um ganho para quem está pior vale mais.'), ('etica-do-cuidado', 'Cuidado', 'A favor: atenção a quem foi deixado de fora, e não só a regras neutras.')],
 licoes=['igualdade-humana', 'tribalismo-moral', 'somar-priorizar-ou-garantir'],
 fx=[('Affirmative Action (Stanford Encyclopedia)', SEP + 'affirmative-action/'), ('Cotas (Política Para Iniciantes)', 'https://politicaparainiciantes.biblioverse.org/debates/cotas.html'), ('Lei de Cotas (Wikipédia)', 'https://pt.wikipedia.org/wiki/Lei_de_Cotas')]),

dict(s='trabalho-sexual', n='Trabalho sexual', t=VP, r='Vender sexo entre adultos: é trabalho como outro, exploração por definição, ou algo que depende das condições?',
 v='A prostituição é legal, regulada, tolerada ou criminalizada conforme o país. O debate ético tem dois níveis: se há algo errado em si na venda de sexo consentido, e qual regime legal protege melhor quem o exerce. As duas perguntas têm respostas diferentes.',
 lados=[('Trabalho, com direitos', ['Autonomia: adultos podem decidir o que fazer com o próprio corpo, inclusive trabalhar com ele, como fazem atletas, modelos e cuidadores.', 'Evidência: criminalizar, inclusive só o cliente (“modelo nórdico”), empurra a atividade para a clandestinidade e aumenta violência e doenças; descriminalizar (Nova Zelândia) melhorou a segurança, segundo as próprias trabalhadoras.', 'Organizações de trabalhadoras sexuais pedem direitos, não resgate.', 'A objeção moral costuma ser repulsa, não argumento.']),
        ('Exploração estrutural', ['A maior parte de quem vende sexo o faz por falta de alternativa; “consentimento” sob pobreza e trauma é frágil.', 'Feminismo abolicionista: a prostituição é uma instituição de dominação masculina, e legalizá-la normaliza a compra de pessoas.', 'Tráfico e exploração de menores se misturam ao mercado legal, e a regulação não os elimina.', 'Kant: vender o uso do próprio corpo para prazer alheio trata a si mesmo como coisa.'])],
 c=['Trabalho sexual voluntário e tráfico são fenômenos diferentes, e misturá-los serve aos dois lados do debate.', 'A pergunta moral (é errado em si?) e a pergunta política (qual regime reduz o dano?) se separam: pode-se achar a prática indesejável e ainda assim preferir a descriminalização.', 'A voz de quem exerce a atividade é dividida, e cada lado cita a parte que lhe convém.'],
 p=('aberto', 'Sobre a política, a evidência pende para a descriminalização: os regimes de criminalização, inclusive do cliente, pioram a segurança de quem exerce a atividade. Sobre a moral da venda de sexo em si, o debate é real: a objeção da exploração estrutural é séria, mas é uma objeção às condições (pobreza, desigualdade de gênero), e não prova que a troca consentida seja errada por si. A filosofia não chegou a consenso, e a repulsa não é argumento.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'Contra criminalizar: a evidência mostra mais dano com a proibição.'), ('deontologia-de-direitos', 'Direitos', 'Autonomia sobre o próprio corpo, inclusive para trabalho.'), ('deontologia-kantiana', 'Kant', 'Contra: vender o uso de si para prazer alheio seria tratar-se como meio.'), ('etica-do-cuidado', 'Cuidado', 'Pergunta pelas condições de quem exerce; a resposta é quase sempre proteção, não prisão.'), ('etica-das-virtudes', 'Virtudes', 'Dividida: o que a prática faz com quem compra e com quem vende.')],
 licoes=['fazer-e-deixar-acontecer', 'pobreza-e-etica-global', 'imparcialidade'],
 fx=[('Feminist Perspectives on Sex Markets (Stanford Encyclopedia)', SEP + 'feminist-sex-markets/'), ('Prostitution law (Wikipédia)', WE + 'Prostitution_law'), ('Decriminalization of sex work (Wikipédia)', WE + 'Decriminalization_of_sex_work')]),
]
